            runs.append((i, j, color))
            i = j
        return runs

    left = edge_runs([grid[r][0] for r in range(h)])
    right = edge_runs([grid[r][-1] for r in range(h)])

    # Opposing vertical edge bars pair rows by their offset within each bar.
    vertical_pairs = [
        (a, b) for a in left for b in right
        if a[2] == b[2] and a[1] - a[0] >= 2 and b[1] - b[0] >= 2
    ]
    if vertical_pairs:
        a, b = max(vertical_pairs, key=lambda p: min(p[0][1]-p[0][0], p[1][1]-p[1][0]))
        marker = a[2]
        dots = [(r, c, grid[r][c]) for r in range(h) for c in range(w)
                if grid[r][c] != bg and grid[r][c] != marker]

        for r, c, color in dots:
            if a[0] <= r < a[1]:
                src, paired = a, b
                # Ray from the left edge to the dot.
                for x in range(1, c):
                    if out[r][x] == bg:
                        out[r][x] = color
                paired_row = paired[0] + (r - src[0])
                # The paired row is filled across the grid from the opposite bar.
                for x in range(w):
                    if out[paired_row][x] == bg:
                        out[paired_row][x] = color
            elif b[0] <= r < b[1]:
                src, paired = b, a
                # Ray from the right edge to the dot.
                for x in range(c + 1, w):
