    bars += [(h - 1, s, e, color, -1) for s, e, color in bottom]

    marker_colors = {color for _, _, _, color, _ in bars}
    dot_counts = Counter(grid[r][c] for r in range(h) for c in range(w)
                         if grid[r][c] != bg and grid[r][c] not in marker_colors)
    default_color = dot_counts.most_common(1)[0][0] if dot_counts else bg

    for edge_r, s, e, marker, dr in bars:
